begin;
create table if not exists public.mme_notification_preferences(preference_id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.mme_crm_customers(customer_id),channel text not null check(channel in('email','sms','in_app')),purpose text not null check(purpose in('marketing','service','transactional')),enabled boolean not null default true,updated_at timestamptz not null default now(),unique(customer_id,channel,purpose));
create table if not exists public.mme_notification_templates(template_id uuid primary key default gen_random_uuid(),template_key text not null unique,channel text not null check(channel in('email','sms','in_app')),purpose text not null check(purpose in('marketing','service','transactional')),subject_template text,body_template text not null,active boolean not null default true,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_notification_rules(rule_id uuid primary key default gen_random_uuid(),rule_key text not null unique,description text not null,trigger_event text not null,template_key text not null references public.mme_notification_templates(template_key),delay_seconds integer not null default 0 check(delay_seconds between 0 and 2592000),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.mme_notifications(notification_id uuid primary key default gen_random_uuid(),customer_id uuid references public.mme_crm_customers(customer_id),recipient text not null,channel text not null check(channel in('email','sms','in_app')),purpose text not null check(purpose in('marketing','service','transactional')),subject text,body text not null,notification_status text not null default 'queued' check(notification_status in('queued','processing','sent','delivered','suppressed','failed','cancelled')),scheduled_at timestamptz not null default now(),attempt_count integer not null default 0 check(attempt_count>=0),max_attempts integer not null default 5 check(max_attempts between 1 and 10),next_attempt_at timestamptz not null default now(),provider_message_id text,provider_response jsonb,created_by_auth_user_id uuid,created_at timestamptz not null default now(),sent_at timestamptz,delivered_at timestamptz,last_error text);
create index if not exists mme_notifications_dispatch_idx on public.mme_notifications(notification_status,next_attempt_at,scheduled_at) where notification_status in('queued','failed');
create index if not exists mme_notifications_customer_idx on public.mme_notifications(customer_id,created_at desc);
create table if not exists public.mme_notification_attempts(attempt_id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.mme_notifications(notification_id),attempt_number integer not null,provider text not null,attempt_status text not null check(attempt_status in('processing','sent','failed')),provider_message_id text,response jsonb,error_message text,attempted_at timestamptz not null default now(),unique(notification_id,attempt_number));
create table if not exists public.mme_notification_events(event_id uuid primary key default gen_random_uuid(),notification_id uuid references public.mme_notifications(notification_id),event_type text not null,actor_auth_user_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.mme_notification_claim_batch(p_limit integer default 20)
returns setof public.mme_notifications language plpgsql security definer set search_path=public as $$
begin
 return query with picked as(select notification_id from public.mme_notifications where notification_status in('queued','failed') and next_attempt_at<=now() and attempt_count<max_attempts order by scheduled_at,created_at for update skip locked limit greatest(1,least(coalesce(p_limit,20),100))) update public.mme_notifications n set notification_status='processing',attempt_count=n.attempt_count+1 from picked where n.notification_id=picked.notification_id returning n.*;
end;$$;
create or replace function public.mme_notification_finish(p_id uuid,p_status text,p_provider text,p_provider_id text,p_response jsonb,p_error text)
returns void language plpgsql security definer set search_path=public as $$
declare n public.mme_notifications%rowtype;
begin
 if p_status not in('sent','failed','suppressed') then raise exception 'invalid_notification_status'; end if;
 update public.mme_notifications set notification_status=p_status,provider_message_id=p_provider_id,provider_response=coalesce(p_response,'{}'::jsonb),last_error=p_error,sent_at=case when p_status='sent' then now() else sent_at end,next_attempt_at=case when p_status='failed' and attempt_count<max_attempts then now()+make_interval(secs=>least(3600,30*power(2,greatest(attempt_count-1,0))::integer)) else next_attempt_at end where notification_id=p_id returning * into n;
 if not found then raise exception 'notification_not_found'; end if;
 insert into public.mme_notification_attempts(notification_id,attempt_number,provider,attempt_status,provider_message_id,response,error_message) values(n.notification_id,n.attempt_count,coalesce(p_provider,'unconfigured'),p_status,p_provider_id,coalesce(p_response,'{}'::jsonb),p_error);
 insert into public.mme_notification_events(notification_id,event_type,metadata) values(n.notification_id,'delivery_'||p_status,jsonb_build_object('attempt',n.attempt_count,'provider',p_provider,'error',p_error));
end;$$;
revoke all on function public.mme_notification_claim_batch(integer) from public,anon,authenticated;
revoke all on function public.mme_notification_finish(uuid,text,text,text,jsonb,text) from public,anon,authenticated;
grant execute on function public.mme_notification_claim_batch(integer) to service_role;
grant execute on function public.mme_notification_finish(uuid,text,text,text,jsonb,text) to service_role;
do $$declare t text;begin foreach t in array array['mme_notification_preferences','mme_notification_templates','mme_notification_rules','mme_notifications','mme_notification_attempts','mme_notification_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;